def checked_int32(n):
    if not -2**31 <= n < 2**31:
        raise OverflowError(n)
    return n


assert checked_int32(2**31 - 1) == 2**31 - 1
try:
    checked_int32(2**31 - 1 + 1)
except OverflowError:
    pass
else:
    raise AssertionError("overflow not detected")
